        dict(role='practice', difficulty='ADVANCED', problem_type='SOURCE_COMMENTARY',
             prompt='Comente el pasaje del discurso de abdicación de Carlos V (Bruselas, 1555). ¿Qué justificación da de su política imperial? ¿Qué hechos del reinado lo contradicen o lo matizan?',
             source=dict(key=ka, quote=ta, author='Carlos V', work='Discurso de abdicación ante los Estados Generales (en traducción inglesa)', date='25 de octubre de 1555', note='Texto citado en la versión inglesa de Wikipedia.'),
             questions=['¿Qué motivos declara para haber buscado la corona imperial?', '¿Qué objetivo religioso y militar menciona?', '¿Qué hechos de su reinado permiten matizar la imagen que da de sí mismo?'],
             answer=dict(sections=[
                dict(label='Qué dice', points=[
                  dict(text='Afirma que se presentó a la corona imperial no para aumentar sus posesiones sino para trabajar por el bienestar de Alemania y sus otros reinos, y para unir a los cristianos contra los otomanos en defensa de la fe católica.', quotes=[Q('en_carlos5','The most famous – and only public – abdication took place a year later, on 25 October 1555'), Q('en_carlos5','not to increase my possessions but rather to engage myself more vigorously in working for the welfare of Germany and my other realms')])]),
                dict(label='Matices', points=[
                  dict(text='La elección imperial costó más de un millón de florines en sobornos y exigió impuestos que provocaron la revuelta de las Comunidades; una fuente califica su sueño de imperio universal de fracasado.', quotes=[Q('en_comuneros','over 1 million florins were spent in bribes for the election'), Q('es_carlos1','Su sueño de un Imperio universal bajo los Habsburgo había fracasado')]),
                  dict(text='Tampoco logró frenar la Reforma: debió firmar la Paz de Augsburgo, que reconocía a los príncipes la elección entre catolicismo y luteranismo.', quotes=[Q('es_carlos1','se vio obligado a suscribir la Paz de Augsburgo'), Q('en_carlos5','The agreements led to the religious division of Germany between Catholic and Protestant princedoms.')])]),
                dict(label='Cautela', points=[
                  dict(text='Es un discurso público de despedida, con intención de justificarse; debe leerse como autoimagen y no como balance objetivo. En él reconoce haberse equivocado, aunque asegura no haber obrado injustamente a sabiendas.', quotes=[Q('en_carlos5','I nonetheless declare to you that I never knowingly or willingly acted unjustly.'), Q('es_carlos1','El balance de su vida y de aquello que había completado no era del todo positivo')])]),
             ],
             mistakes=['Aceptar la justificación del emperador como si fuera una explicación neutral de sus motivos.'],
             criteria=['Separa lo que dice el texto de lo que dicen otras fuentes.', 'Contextualiza el discurso.'])),
        dict(role='practice', difficulty='ADVANCED', problem_type='CAUSAL_ANALYSIS',
             prompt='¿Por qué fracasó la revuelta de las Comunidades? Distinga factores militares, políticos y sociales, y valore sus consecuencias a medio plazo.',
             answer=dict(sections=[
                dict(label='Factores militares', points=[dict(text='Villalar: Padilla no logró desplegar a sus casi 6000 hombres bajo la lluvia y la caballería realista los aplastó; los tres jefes fueron decapitados al día siguiente de la batalla.', quotes=[Q('es_comunidades','la caballería realista, compuesta por unas 500 o 600 lanzas, aplastó al ejército rebelde'), Q('en_comuneros','the reorganized supporters of the emperor struck a crippling blow to the comuneros at the Battle of Villalar')])]),
                dict(label='Factores políticos y sociales', points=[
                  dict(text='La rebelión quedó limitada a la meseta: las cuatro ciudades andaluzas no acudieron a Tordesillas.', quotes=[Q('es_comunidades','Solamente no acudieron las cuatro ciudades andaluzas'), Q('es_comunidades','La zona que más sufre en este contexto es la zona central')]),
                  dict(text='La nobleza, que sentía amenazado su poder por las revueltas, se organizó con el Almirante y el Condestable para derrotar a los comuneros.', quotes=[Q('es_comunidades','las tropas realistas del Almirante y el Condestable'), Q('en_comuneros','the reorganized supporters of the emperor')])]),
                dict(label='Consecuencias', points=[dict(text='Pérdida de la élite política de las ciudades, impuestos de indemnización durante unos veinte años y neutralización de la nobleza; el rey amnistió con el Perdón General de 1522, salvo a 293 personas.', quotes=[Q('es_comunidades','Estos impuestos mermaron las economías locales de las ciudades durante un periodo aproximado de veinte años'), Q('es_comunidades','fueron excluidas del Perdón General')])]),
             ],
             mistakes=['Explicar el fracaso solo por una batalla.', 'Describir los comuneros como un bloque uniforme: Toledo y María Pacheco resistieron más.'])),
